<?php
declare(strict_types=1);
use PHPUnit\Framework\TestCase;
if(!defined('CLUB_MIGRATION_MEMORY_TEST'))define('CLUB_MIGRATION_MEMORY_TEST',true);
require_once dirname(__DIR__,2).'/includes/club_migration.php';
final class ClubMigrationTest extends TestCase {
 private function db():PDO {
  $p=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$p->exec('PRAGMA foreign_keys=ON');
  $p->exec("CREATE TABLE treneri(id INTEGER PRIMARY KEY,aktivni INT,jmeno TEXT,email TEXT);INSERT INTO treneri VALUES(1,1,'TEST Registrar','reg@example.invalid'),(2,1,'TEST Sports Lead','lead@example.invalid'),(3,1,'TEST Coach','coach@example.invalid')");$p->exec("CREATE TABLE staff_user_positions(trainer_id INT,position_code TEXT);INSERT INTO staff_user_positions VALUES(1,'registrar'),(2,'sports_lead'),(3,'coach')");$p->exec('CREATE TABLE staff_superadmins(trainer_id INT);INSERT INTO staff_superadmins VALUES(1)');
  $p->exec("CREATE TABLE sportovci(id INTEGER PRIMARY KEY,jmeno TEXT,prijmeni TEXT,narozeni TEXT,email TEXT);INSERT INTO sportovci VALUES(10,'TEST','Athlete','2010-01-01','athlete@example.invalid')");
  $p->exec('CREATE TABLE treninky(id INTEGER PRIMARY KEY AUTOINCREMENT,datum TEXT,napln TEXT,poznamka TEXT,delka REAL,kategorie TEXT)');$p->exec('CREATE TABLE trenink_sportovec(trenink_id INT,sportovec_id INT)');$p->exec('CREATE TABLE trenink_trener(trenink_id INT,trener_id INT)');
  $p->exec('CREATE TABLE club_events(id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT UNIQUE,event_type TEXT,name TEXT,description_plain TEXT,audience_label TEXT,capacity INT,pricing_policy TEXT,currency TEXT,status TEXT,created_by_trainer_id INT,activity_kind TEXT,planning_status TEXT,internal_note TEXT)');
  $p->exec('CREATE TABLE club_event_sessions(id INTEGER PRIMARY KEY,event_id INT,starts_at TEXT,ends_at TEXT)');
  foreach(['20261022210000_person_identity_reviews','20261023020000_training_closure','20261023030000_sports_activity','20261023080000_club_migration'] as $m){$migration=require dirname(__DIR__,2).'/migrations/'.$m.'.php';$migration['up']($p);self::assertTrue($migration['verify']($p));}
  $p->exec("INSERT INTO person_identity_reviews(source_namespace,source_id,source_fingerprint,first_name,last_name,birth_date,candidate_ids_json,status,sportovec_id,reason,evidence_ref,created_by_trainer_id) VALUES('TEST-evidence','person-1','testhash','TEST','Athlete','2010-01-01','[10]','verified',10,'TEST verified documentary identity','TEST paper identity proof',1)");$this->as(1);return $p;
 }
 private function as(int $actor):void {$pos=[1=>'registrar',2=>'sports_lead',3=>'coach'][$actor];$_SESSION=['trener_id'=>$actor,'staff_positions'=>[$pos],'staff_active_position'=>$pos];}
 private function payload(array $records):array{return ['contract'=>'club-migration.synthetic.v1','synthetic_only'=>true,'timezone'=>'Europe/Prague','source_namespace'=>'TEST-evidence','window_from'=>'2026-01-01 00:00:00','window_to'=>'2026-02-01 00:00:00','records'=>$records];}
 private function record(string $type,string $source,array $data):array{return ['type'=>$type,'source_id'=>$source,'data'=>$data];}
 private function person():array{return $this->record('person','person-1',['first_name'=>'TEST','last_name'=>'Athlete','birth_date'=>'2010-01-01']);}
 private function review(PDO $p,int $id,array $proposal=[],string $decision='approve'):array{$i=clubMigrationItem($p,$id);return clubMigrationReview($p,$id,(int)$i['revision'],$decision,$proposal,$i['source_hash'],(int)$_SESSION['trener_id'],'TEST explicitly reviewed source evidence');}
 private function apply(PDO $p,int $batch,int $limit=100):array{return clubMigrationApply($p,$batch,clubMigrationPlanHash($p,$batch),(int)$_SESSION['trener_id'],$limit);}
 private function link(PDO $p):int{$b=clubMigrationStage($p,$this->payload([$this->person(),$this->record('trainer','coach-1',['name'=>'TEST Coach'])]),1);$this->review($p,1,['target_id'=>10,'identity_review_id'=>1,'identity_evidence'=>'TEST verified documentary identity']);$this->review($p,2,['target_id'=>3,'identity_evidence'=>'TEST approved coach identity']);$this->apply($p,$b);return $b;}
 private function denied(callable $f,string $text=''):void{try{$f();self::fail('Expected refusal');}catch(DomainException $e){self::assertNotSame('',$e->getMessage());if($text!=='')self::assertStringContainsString($text,$e->getMessage());}}
 private function training(array $overrides=[]):array{return $this->record('training','training-1',array_replace(['actual_confirmed'=>true,'started_at'=>'2026-01-10 10:00:00','ended_at'=>'2026-01-10 11:00:00','participant_source_ids'=>['person-1'],'coach_source_ids'=>['coach-1'],'category'=>'silnice','label'=>'TEST historical actual training'],$overrides));}
 protected function tearDown():void{$_SESSION=[];}
 public function testStageRetryAndUnknownIdentityNeverCreatePeople():void{$p=$this->db();$payload=$this->payload([$this->person()]);$b=clubMigrationStage($p,$payload,1);self::assertSame($b,clubMigrationStage($p,$payload,1));$p->exec("UPDATE person_identity_reviews SET status='review'");$this->denied(fn()=>$this->review($p,1,['target_id'=>10,'identity_review_id'=>1,'identity_evidence'=>'TEST reviewed candidate']),'Identita');self::assertSame(1,(int)$p->query('SELECT COUNT(*) FROM sportovci')->fetchColumn());self::assertSame(0,(int)$p->query('SELECT COUNT(*) FROM club_migration_maps')->fetchColumn());}
 public function testExplicitMapsPreserveCurrentPeopleAndDoNotGrantRoles():void{$p=$this->db();$before=$p->query('SELECT * FROM sportovci')->fetchAll();$b=$this->link($p);self::assertSame($before,$p->query('SELECT * FROM sportovci')->fetchAll());self::assertSame(2,clubMigrationReport($p,$b)['counts']['linked']);self::assertSame(3,(int)$p->query('SELECT COUNT(*) FROM staff_user_positions')->fetchColumn());self::assertSame(2,$this->apply($p,$b)['counts']['linked']);}
 public function testTargetChangeAfterReviewCannotOverwrite():void{$p=$this->db();$b=clubMigrationStage($p,$this->payload([$this->person()]),1);$this->review($p,1,['target_id'=>10,'identity_review_id'=>1,'identity_evidence'=>'TEST identity verified']);$p->exec("UPDATE sportovci SET email='new@example.invalid' WHERE id=10");$this->denied(fn()=>$this->apply($p,$b),'změnily');self::assertSame(0,(int)$p->query('SELECT COUNT(*) FROM club_migration_maps')->fetchColumn());self::assertSame('new@example.invalid',$p->query('SELECT email FROM sportovci')->fetchColumn());}
 public function testReplayAfterTargetChangeFailsInsteadOfRestoringOldValues():void{$p=$this->db();$b=$this->link($p);$p->exec("UPDATE sportovci SET jmeno='NEW CURRENT NAME' WHERE id=10");$this->denied(fn()=>$this->apply($p,$b),'cíl se změnil');self::assertSame('NEW CURRENT NAME',$p->query('SELECT jmeno FROM sportovci')->fetchColumn());}
 public function testSourceChangeUnderStableIdRequiresReviewAndTombstoneNeverDeletes():void{$p=$this->db();$this->link($p);$r=$this->person();$r['data']['first_name']='Different';$b=clubMigrationStage($p,$this->payload([$r]),1);$this->denied(fn()=>$this->review($p,3,['target_id'=>10,'identity_review_id'=>1,'identity_evidence'=>'TEST changed source']),'jiný obsah');$this->review($p,3,[],'quarantine');$delete=$this->person();$delete['tombstone']=true;$b2=clubMigrationStage($p,$this->payload([$delete]),1);$this->denied(fn()=>$this->review($p,4,[]),'Výmaz');self::assertSame(1,(int)$p->query('SELECT COUNT(*) FROM sportovci')->fetchColumn());self::assertSame(1,clubMigrationReport($p,$b2)['counts']['quarantine']);}
 public function testActualTrainingAddsCanonicalHistoryExactlyOnceWithoutRewardsOrMakeups():void{$p=$this->db();$this->link($p);$this->as(2);$b=clubMigrationStage($p,$this->payload([$this->training()]),2);$this->review($p,3);$this->apply($p,$b);$this->apply($p,$b);self::assertSame(1,(int)$p->query('SELECT COUNT(*) FROM treninky')->fetchColumn());$s=sportsActivitySummary($p,10,'2026-01-01','2026-01-31');self::assertSame(1,$s['training_count']);self::assertSame(60,$s['training_minutes']);self::assertSame('migration',json_decode($p->query('SELECT snapshot_json FROM training_closure_revisions')->fetchColumn(),true)['record_source']);}
 public function testFutureActivityAndMissingCoachMapQuarantine():void{$p=$this->db();$this->link($p);$this->as(2);$b=clubMigrationStage($p,$this->payload([$this->training(['started_at'=>'2099-01-01 10:00:00','ended_at'=>'2099-01-01 11:00:00'])]),2);$this->denied(fn()=>$this->review($p,3),'budoucí');$this->review($p,3,[],'quarantine');self::assertSame(0,(int)$p->query('SELECT COUNT(*) FROM treninky')->fetchColumn());}
 public function testPartialResumeSamePlanDoesNotDuplicate():void{$p=$this->db();$b=clubMigrationStage($p,$this->payload([$this->person(),$this->record('trainer','coach-1',['name'=>'TEST Coach'])]),1);$this->review($p,1,['target_id'=>10,'identity_review_id'=>1,'identity_evidence'=>'TEST identity proof']);$this->review($p,2,['target_id'=>3,'identity_evidence'=>'TEST coach mapping']);$hash=clubMigrationPlanHash($p,$b);self::assertSame(1,clubMigrationApply($p,$b,$hash,1,1)['counts']['linked']);self::assertSame(2,clubMigrationApply($p,$b,$hash,1,1)['counts']['linked']);self::assertSame(2,(int)$p->query('SELECT COUNT(*) FROM club_migration_maps')->fetchColumn());}
 public function testChangedPlanAndSourceBytesInvalidateApproval():void{$p=$this->db();$b=clubMigrationStage($p,$this->payload([$this->person()]),1);$hash=clubMigrationPlanHash($p,$b);$this->review($p,1,['target_id'=>10,'identity_review_id'=>1,'identity_evidence'=>'TEST identity proof']);$this->denied(fn()=>clubMigrationApply($p,$b,$hash,1),'Náhled');$hash=clubMigrationPlanHash($p,$b);$p->exec("UPDATE club_migration_items SET payload_json='{}' WHERE id=1");$this->denied(fn()=>clubMigrationApply($p,$b,$hash,1),'Obsah');}
 public function testActorRevocationAndStaffMappingPrivilege():void{$p=$this->db();$b=clubMigrationStage($p,$this->payload([$this->record('trainer','coach-1',['name'=>'TEST Coach'])]),1);$p->exec('DELETE FROM staff_superadmins');$this->denied(fn()=>$this->review($p,1,['target_id'=>3,'identity_evidence'=>'TEST coach authority']),'správce');$p->exec('DELETE FROM staff_user_positions WHERE trainer_id=1');$this->denied(fn()=>clubMigrationStage($p,$this->payload([]),1),'neplatí');}
 public function testHistoricalResultHasCanonicalEventAndSingleActualStart():void{$p=$this->db();$this->link($p);$this->as(2);$b=clubMigrationStage($p,$this->payload([$this->record('event','event-1',['label'=>'TEST race','date'=>'2026-01-10','activity_kind'=>'race'])]),2);$this->review($p,3);$this->apply($p,$b);$b2=clubMigrationStage($p,$this->payload([$this->record('result','result-1',['person_source_id'=>'person-1','event_source_id'=>'event-1','stage'=>'started','actual_date'=>'2026-01-10','result_status'=>'DNF','result_value'=>'','result_unit'=>''])]),2);$this->review($p,4);$this->apply($p,$b2);$this->apply($p,$b2);self::assertSame(1,sportsActivitySummary($p,10,'2026-01-01','2026-01-31')['race_count']);self::assertSame(1,(int)$p->query('SELECT COUNT(*) FROM club_events')->fetchColumn());self::assertSame(1,(int)$p->query('SELECT COUNT(*) FROM sports_event_revisions')->fetchColumn());}
 public function testRealInputAndDuplicateSourceRowsDenied():void{$p=$this->db();$payload=$this->payload([$this->person()]);$payload['synthetic_only']=false;$this->denied(fn()=>clubMigrationStage($p,$payload,1),'syntetické');$this->denied(fn()=>clubMigrationStage($p,$this->payload([$this->person(),$this->person()]),1),'duplicitní');}
 public function testExistingCanonicalActivityRequiresExplicitExactLink():void{$p=$this->db();$this->link($p);$this->as(2);$b=clubMigrationStage($p,$this->payload([$this->training()]),2);$this->review($p,3);$this->apply($p,$b);$duplicate=$this->training();$duplicate['source_id']='different-source-training';$b2=clubMigrationStage($p,$this->payload([$duplicate]),2);$this->denied(fn()=>$this->review($p,4),'stejnou aktivitu');$this->review($p,4,['target_id'=>1,'identity_evidence'=>'TEST exact historic duplicate verified']);$this->apply($p,$b2);self::assertSame(1,(int)$p->query('SELECT COUNT(*) FROM treninky')->fetchColumn());self::assertSame(1,clubMigrationReport($p,$b2)['counts']['linked']);}
 public function testEmptyAndMissingTimezoneCannotPassRehearsal():void{$p=$this->db();$b=clubMigrationStage($p,$this->payload([]),1);self::assertSame('review_required',clubMigrationReport($p,$b)['state']);$payload=$this->payload([]);unset($payload['timezone']);$this->denied(fn()=>clubMigrationStage($p,$payload,1),'časové pásmo');}
 public function testConcurrentDifferentApprovedTargetsCannotHijackMap():void{$p=$this->db();$r=$this->record('trainer','coach-race',['name'=>'TEST old coach']);$first=$this->payload([$r]);$b1=clubMigrationStage($p,$first,1);$second=$first;$second['window_to']='2026-02-02 00:00:00';$b2=clubMigrationStage($p,$second,1);$this->review($p,1,['target_id'=>3,'identity_evidence'=>'TEST first explicit mapping']);$this->review($p,2,['target_id'=>2,'identity_evidence'=>'TEST different explicit mapping']);$this->apply($p,$b1);$this->denied(fn()=>$this->apply($p,$b2),'schválenému cíli');self::assertSame(3,(int)clubMigrationMap($p,'TEST-evidence','trainer','coach-race')['target_id']);self::assertSame('approved',clubMigrationItem($p,2)['state']);}
 public function testArchiveNeedsTypedRoleAndNeverMeansCompletedMigration():void{$p=$this->db();$b=clubMigrationStage($p,$this->payload([$this->person(),$this->training()]),1);$this->review($p,1,[],'archive');self::assertSame('review_required',clubMigrationReport($p,$b)['state']);$this->denied(fn()=>$this->review($p,2,[],'archive'),'pozici');}
 public function testReservedTombstoneCannotOverrideDeletionFlag():void{$p=$this->db();$r=$this->person();$r['tombstone']=true;$r['data']['_tombstone']=false;$this->denied(fn()=>clubMigrationStage($p,$this->payload([$r]),1),'vyhrazený');}
 public function testFamilyRoleMustResolveActualPersonAndAccountMaps():void{$p=$this->db();$this->link($p);$p->exec("CREATE TABLE account_person_roles(id INT,account_id INT,sportovec_id INT,status TEXT,relation_role TEXT,valid_from TEXT,valid_to TEXT);INSERT INTO account_person_roles VALUES(77,88,99,'approved','guardian','2026-01-01',NULL)");$b=clubMigrationStage($p,$this->payload([$this->record('family_role','family-1',['person_source_id'=>'person-1','account_source_id'=>'OTHER-FAMILY','relation_role'=>'guardian','valid_from'=>'2026-01-01','valid_to'=>null])]),1);$this->denied(fn()=>$this->review($p,3,['target_id'=>77,'identity_evidence'=>'TEST generic claimed family proof']),'Chybí');self::assertSame(99,(int)$p->query('SELECT sportovec_id FROM account_person_roles')->fetchColumn());}
 public function testFullSourceArchiveAndConverterFingerprintInvalidateApproval():void{$p=$this->db();$b=clubMigrationStage($p,$this->payload([$this->person()]),1);$v=$this->review($p,1,['target_id'=>10,'identity_review_id'=>1,'identity_evidence'=>'TEST verified identity']);$proposal=json_decode($v['proposal_json'],true);$proposal['_converter_sha256']=str_repeat('0',64);$p->prepare('UPDATE club_migration_items SET proposal_json=? WHERE id=1')->execute([clubMigrationJson($proposal)]);$this->denied(fn()=>$this->apply($p,$b),'Převodník');$manifest=json_decode(clubMigrationBatch($p,$b)['manifest_json'],true);$manifest['source_payload']['records'][0]['data']['first_name']='TAMPERED';$p->prepare('UPDATE club_migration_batches SET manifest_json=? WHERE id=?')->execute([clubMigrationJson($manifest),$b]);$this->denied(fn()=>$this->apply($p,$b),'zdrojový snímek');}
}
